import type { Question } from "@/lib/questionBank";

// Reproductive Health — generated by Claude (no source PDF supplied for this chapter).
// Covers reproductive/child health programmes, STDs, contraceptive methods, medical
// termination of pregnancy, infertility and assisted reproductive technologies, and
// the misuse of amniocentesis for sex determination.

const questions: Question[] = [
  // ---- MCQ ----
  { id: 'rh-1', type: 'mcq', question: 'Reproductive health, as defined by WHO, refers to:', options: ['Merely the absence of any reproductive disease', 'Total wellbeing in all aspects of reproduction — physical, emotional, behavioural, and social', 'Only the physical fitness of reproductive organs', 'Only the absence of sexually transmitted diseases'], correctIndex: 1, explanation: 'Reproductive health is a holistic state of wellbeing across all dimensions of reproduction, not merely disease absence.', difficulty: 'easy' },
  { id: 'rh-2', type: 'mcq', question: 'The Reproductive and Child Health Care (RCH) programmes in India were launched with the goal of:', options: ['Increasing population growth rate', 'Creating reproductively healthy society', 'Banning all forms of contraception', 'Eliminating sex education entirely'], correctIndex: 1, explanation: 'RCH programmes aim to build a reproductively healthy population through various health initiatives.', difficulty: 'medium' },
  { id: 'rh-3', type: 'mcq', question: 'Providing sex education in schools is considered important mainly because it helps:', options: ['Encourage early sexual activity', 'Provide correct information and discourage myths/misconceptions about sex-related issues', 'Replace all biology curricula', 'Increase population growth'], correctIndex: 1, explanation: 'Proper sex education counters misinformation and myths, supporting informed decisions about reproductive health.', difficulty: 'medium' },
  { id: 'rh-4', type: 'mcq', question: 'Which of the following is generally recommended as part of reproductive health awareness programmes?', options: ['Discouraging medical care during pregnancy', 'Awareness about the reproductive phase of life and related changes', 'Promoting early marriage', 'Discouraging postnatal care'], correctIndex: 1, explanation: 'Awareness about pubertal changes, adolescence, and reproductive processes is a core part of health education.', difficulty: 'medium' },
  { id: 'rh-5', type: 'mcq', question: 'Sexually Transmitted Diseases (STDs), also called Reproductive Tract Infections (RTIs), are diseases or infections that are transmitted through:', options: ['Only blood transfusion', 'Sexual contact/intercourse', 'Only contaminated water', 'Only insect vectors'], correctIndex: 1, explanation: 'STDs/RTIs are infections transmitted through sexual contact.', difficulty: 'easy' },
  { id: 'rh-6', type: 'mcq', question: 'Which of the following is a common example of a sexually transmitted disease?', options: ['Malaria', 'Gonorrhoea', 'Tuberculosis', 'Chickenpox'], correctIndex: 1, explanation: 'Gonorrhoea is a classic bacterial sexually transmitted disease.', difficulty: 'easy' },
  { id: 'rh-7', type: 'mcq', question: 'Which of the following is a viral sexually transmitted disease?', options: ['Syphilis', 'Gonorrhoea', 'Genital herpes', 'Trichomoniasis'], correctIndex: 2, explanation: 'Genital herpes is caused by a virus, unlike syphilis and gonorrhoea, which are bacterial.', difficulty: 'medium' },
  { id: 'rh-8', type: 'mcq', question: 'Among STDs, which of the following can be completely cured if detected early and treated properly, EXCEPT:', options: ['Gonorrhoea', 'Syphilis', 'HIV/AIDS and genital herpes', 'Chlamydia infections'], correctIndex: 2, explanation: 'HIV/AIDS and genital herpes are examples of STDs that are not fully curable, unlike most bacterial STDs.', difficulty: 'medium' },
  { id: 'rh-9', type: 'mcq', question: 'Early detection and proper treatment of STDs is important mainly because untreated infections can lead to:', options: ['Improved fertility', 'Complications such as infertility, and can also be transmitted to the foetus in pregnant women', 'No long-term consequences at all', 'Enhanced immune function'], correctIndex: 1, explanation: 'Untreated STDs can cause serious complications, including infertility and vertical transmission to a foetus.', difficulty: 'medium' },
  { id: 'rh-10', type: 'mcq', question: "The practice of avoiding multiple sexual partners and using barrier methods (like condoms) during intercourse mainly helps prevent:", options: ['Menstrual disorders', 'STDs', 'Menopause symptoms', 'Congenital anomalies unrelated to infection'], correctIndex: 1, explanation: 'Being mutually faithful to a single partner and using barrier contraceptives are key strategies to prevent STDs.', difficulty: 'medium' },
  { id: 'rh-11', type: 'mcq', question: 'An ideal contraceptive method should have which of the following characteristics?', options: ['User-friendly, effective, reversible, with no or few side effects', 'Extremely expensive and inconvenient', 'Cause permanent infertility in all cases', 'Have no effect on the menstrual cycle regardless of method'], correctIndex: 0, explanation: 'An ideal contraceptive is user-friendly, reliable, reversible (except permanent methods), and largely free of side effects.', difficulty: 'medium' },
  { id: 'rh-12', type: 'mcq', question: 'The "natural" or "rhythm" method of contraception, where couples avoid coitus during the fertile period, relies on:', options: ['Surgical intervention', 'Avoiding intercourse from day 10 to day 17 of the menstrual cycle (the likely fertile period)', 'Hormonal pills', 'Barrier devices'], correctIndex: 1, explanation: 'The natural/rhythm method avoids coitus during the estimated fertile window without any device or hormone use.', difficulty: 'medium' },
  { id: 'rh-13', type: 'mcq', question: "'Coitus interruptus' or withdrawal method as a natural contraceptive method involves:", options: ['Using a barrier device', 'The male partner withdrawing the penis from the vagina just before ejaculation', 'Taking hormonal pills', 'Undergoing surgical sterilisation'], correctIndex: 1, explanation: 'Withdrawal before ejaculation is the basis of the coitus interruptus method.', difficulty: 'medium' },
  { id: 'rh-14', type: 'mcq', question: 'Lactational amenorrhea, used as a natural contraceptive method, relies on the fact that:', options: ['Ovulation and menstrual cycles typically do not occur during intense breastfeeding for a limited period post-partum', 'Breastfeeding always causes infertility permanently', 'It is a barrier method', 'It requires a surgical procedure'], correctIndex: 0, explanation: 'Intense breastfeeding suppresses ovulation for a limited postpartum period, providing temporary natural contraception.', difficulty: 'medium' },
  { id: 'rh-15', type: 'mcq', question: 'Barrier methods of contraception work mainly by:', options: ['Altering hormone levels', 'Physically preventing sperm from reaching the egg (e.g., condoms, diaphragms, cervical caps)', 'Permanently blocking gamete-producing organs', 'Preventing implantation via a copper device'], correctIndex: 1, explanation: 'Barrier methods create a physical block preventing sperm-egg contact.', difficulty: 'easy' },
  { id: 'rh-16', type: 'mcq', question: 'Condoms used as barrier contraceptives are made of which material and can be used by:', options: ['Latex rubber/thin plastic; used by both males and females', 'Only stainless steel; used exclusively by males', 'Only cotton fabric; used exclusively by females', 'Only silicone; used exclusively by males'], correctIndex: 0, explanation: 'Condoms, made of thin latex/rubber or plastic, are available for both male and female use.', difficulty: 'medium' },
  { id: 'rh-17', type: 'mcq', question: 'An added benefit of using condoms as a contraceptive method is that they:', options: ['Increase the risk of STDs', 'Help prevent STDs and HIV infection in addition to preventing pregnancy', 'Are effective for permanent sterilisation', 'Require no user compliance at all'], correctIndex: 1, explanation: 'Condoms offer the dual benefit of contraception and protection against STDs/HIV.', difficulty: 'medium' },
  { id: 'rh-18', type: 'mcq', question: 'Intra-Uterine Devices (IUDs) are inserted into the:', options: ['Vagina only', 'Uterus by trained health personnel', 'Ovary directly', 'Fallopian tube exclusively'], correctIndex: 1, explanation: 'IUDs are placed inside the uterus by a trained professional.', difficulty: 'medium' },
  { id: 'rh-19', type: 'mcq', question: 'Copper-releasing IUDs (like CuT) primarily prevent pregnancy by:', options: ['Suppressing ovulation completely', 'Releasing copper ions that make the uterus unsuitable for implantation and are toxic to sperm', 'Blocking the fallopian tubes surgically', 'Killing the egg before ovulation'], correctIndex: 1, explanation: 'Copper ions released by CuT IUDs increase phagocytosis of sperm and create conditions hostile to implantation.', difficulty: 'medium' },
  { id: 'rh-20', type: 'mcq', question: 'Hormone-releasing IUDs work mainly by:', options: ['Physically blocking sperm entirely', 'Making the uterus unsuitable for implantation and the cervix hostile to sperm through hormone release', 'Increasing fertility temporarily', 'Requiring surgical removal of the uterus'], correctIndex: 1, explanation: 'Hormone-releasing IUDs alter the uterine environment and cervical mucus, hindering fertilisation and implantation.', difficulty: 'medium' },
  { id: 'rh-21', type: 'mcq', question: 'IUDs are considered a popular contraceptive choice particularly for women who want to:', options: ['Undergo permanent sterilisation', 'Delay their first pregnancy or space births', 'Never use any hormonal method', 'Avoid any doctor visits at all'], correctIndex: 1, explanation: 'IUDs are widely used by women wanting to delay pregnancy or space between children.', difficulty: 'medium' },
  { id: 'rh-22', type: 'mcq', question: 'Oral contraceptive pills primarily work by:', options: ['Blocking the fallopian tubes', 'Inhibiting ovulation and/or implantation through altered hormone levels', 'Killing sperm directly on contact', 'Physically blocking the cervix'], correctIndex: 1, explanation: 'Oral pills use hormones (progestogen or progestogen-oestrogen combinations) to inhibit ovulation and implantation.', difficulty: 'medium' },
  { id: 'rh-23', type: 'mcq', question: 'Saheli, an oral contraceptive developed in India, is notable for being:', options: ['A steroidal daily-use pill', 'A once-a-week non-steroidal pill', 'An injectable method only', 'A permanent sterilisation method'], correctIndex: 1, explanation: "Saheli is a non-steroidal preparation taken once a week, developed by Indian scientists.", difficulty: 'medium' },
  { id: 'rh-24', type: 'mcq', question: 'Contraceptive methods administered as injections or implants under the skin release hormones that act by:', options: ['Preventing ovulation and/or implantation over an extended period', 'Providing permanent, irreversible sterilisation', 'Working only for a single day', 'Physically blocking the cervix'], correctIndex: 0, explanation: 'Injectable/implant hormonal contraceptives provide longer-acting suppression of ovulation/implantation.', difficulty: 'medium' },
  { id: 'rh-25', type: 'mcq', question: 'Emergency contraceptive pills are typically used:', options: ['As a regular daily contraceptive', 'Within a specific short time window after unprotected intercourse to prevent pregnancy', 'Only as a permanent sterilisation method', 'Only during pregnancy'], correctIndex: 1, explanation: 'Emergency contraceptives are taken shortly after unprotected coitus, preventing ovulation/implantation as a backup measure.', difficulty: 'medium' },
  { id: 'rh-26', type: 'mcq', question: 'Surgical methods of contraception (sterilisation) in males involve a procedure called:', options: ['Tubectomy', 'Vasectomy', 'Hysterectomy', 'Laparoscopy only'], correctIndex: 1, explanation: 'Vasectomy is the male sterilisation procedure, involving cutting/blocking the vas deferens.', difficulty: 'easy' },
  { id: 'rh-27', type: 'mcq', question: 'Surgical methods of contraception (sterilisation) in females involve a procedure called:', options: ['Vasectomy', 'Tubectomy', 'Circumcision', 'Episiotomy'], correctIndex: 1, explanation: 'Tubectomy is the female sterilisation procedure, involving removal/blocking a part of the fallopian tube.', difficulty: 'easy' },
  { id: 'rh-28', type: 'mcq', question: 'In a vasectomy, the surgical procedure involves cutting and blocking a small part of the:', options: ['Vas deferens', 'Fallopian tube', 'Cervix', 'Uterus'], correctIndex: 0, explanation: 'Vasectomy blocks the vas deferens, preventing sperm from being included in the ejaculate.', difficulty: 'medium' },
  { id: 'rh-29', type: 'mcq', question: 'In a tubectomy, the surgical procedure involves cutting and blocking a small part of the:', options: ['Vas deferens', 'Oviduct (fallopian tube)', 'Urethra', 'Prostate'], correctIndex: 1, explanation: 'Tubectomy involves cutting/blocking a part of the fallopian tubes, preventing ova from meeting sperm.', difficulty: 'medium' },
  { id: 'rh-30', type: 'mcq', question: 'Sterilisation methods like vasectomy and tubectomy are considered:', options: ['Highly effective but easily reversible', 'Highly effective permanent contraceptive methods', 'Ineffective compared to natural methods', 'Only used for temporary contraception'], correctIndex: 1, explanation: 'Surgical sterilisation methods are highly effective and generally considered permanent.', difficulty: 'medium' },
  { id: 'rh-31', type: 'mcq', question: 'Medical Termination of Pregnancy (MTP), or induced abortion, refers to:', options: ['A natural miscarriage occurring spontaneously', 'The intentional/voluntary termination of pregnancy before full term', 'A permanent sterilisation procedure', 'A method of contraception used before intercourse'], correctIndex: 1, explanation: 'MTP is a deliberate, medically induced termination of pregnancy before full term.', difficulty: 'easy' },
  { id: 'rh-32', type: 'mcq', question: 'MTPs are considered relatively safe during which period of pregnancy?', options: ['Entire nine months equally', 'The first trimester', 'Only the third trimester', 'Only after full-term delivery'], correctIndex: 1, explanation: 'MTP is considered safest when performed during the first trimester of pregnancy.', difficulty: 'medium' },
  { id: 'rh-33', type: 'mcq', question: 'Legalisation of MTP in many countries, including India, has helped reduce:', options: ['The number of safe deliveries', 'Cases of illegal and unsafe abortions', 'The availability of contraceptives', 'The rate of population growth to zero'], correctIndex: 1, explanation: 'Legal, medically supervised MTP has significantly reduced deaths and complications from unsafe illegal abortions.', difficulty: 'medium' },
  { id: 'rh-34', type: 'mcq', question: 'Infertility, a significant reproductive health concern, refers to the inability of a couple to:', options: ['Have any sexual relationship', 'Conceive or produce a child despite unprotected coitus', 'Undergo any medical procedure', 'Complete a normal pregnancy term once conceived'], correctIndex: 1, explanation: 'Infertility means being unable to conceive/produce children despite trying via unprotected intercourse.', difficulty: 'medium' },
  { id: 'rh-35', type: 'mcq', question: 'Assisted Reproductive Technologies (ART) refer to a group of techniques that help:', options: ['Prevent all forms of pregnancy', 'Infertile couples have children', 'Permanently sterilise both partners', 'Diagnose STDs exclusively'], correctIndex: 1, explanation: 'ART encompasses various techniques (like IVF) that help infertile couples achieve pregnancy.', difficulty: 'medium' },
  { id: 'rh-36', type: 'mcq', question: "In Vitro Fertilisation (IVF), commonly known as the 'test tube baby' technique, involves:", options: ['Fertilisation occurring naturally inside the body', 'Fertilisation of ova and sperm outside the body, in a laboratory setting', 'Only hormonal treatment with no fertilisation step', 'Surgical removal of the uterus'], correctIndex: 1, explanation: "IVF involves fertilising the egg with sperm outside the body ('in vitro'), in laboratory conditions.", difficulty: 'medium' },
  { id: 'rh-37', type: 'mcq', question: 'After fertilisation in an IVF procedure, the resulting embryo is typically:', options: ['Discarded automatically', 'Transferred into the fallopian tube (as a ZIFT) or the uterus (as an IVFET), depending on the stage', 'Left indefinitely in the laboratory', 'Immediately implanted into an unrelated donor'], correctIndex: 1, explanation: 'Depending on developmental stage, the embryo is transferred to the fallopian tube (ZIFT) or the uterus (IVFET).', difficulty: 'medium' },
  { id: 'rh-38', type: 'mcq', question: 'ZIFT stands for:', options: ['Zygote Intra-Fallopian Transfer', 'Zona Interruption Fertility Technique', 'Zonal Implantation Fertility Test', 'Zygote Insertion into Foetal Tissue'], correctIndex: 0, explanation: 'ZIFT (Zygote Intra-Fallopian Transfer) involves transferring an early embryo (up to 8 blastomeres) into the fallopian tube.', difficulty: 'medium' },
  { id: 'rh-39', type: 'mcq', question: 'GIFT (Gamete Intra-Fallopian Transfer) is a technique in which:', options: ['A fully developed embryo is placed in the uterus', 'Ova collected from a donor are transferred into the fallopian tube of a recipient who cannot produce her own ova', 'Sperm are transferred to the vagina', 'The uterus is surgically removed'], correctIndex: 1, explanation: 'GIFT involves transferring donor ova into a recipient\'s fallopian tube when she cannot produce her own.', difficulty: 'medium' },
  { id: 'rh-40', type: 'mcq', question: 'Intracytoplasmic Sperm Injection (ICSI) is a specialised ART technique in which:', options: ['A whole sperm is placed near the egg for natural fertilisation', 'A single sperm is directly injected into the cytoplasm of the ovum to induce fertilisation', 'Two embryos are combined into one', 'The egg is transferred without any sperm involvement'], correctIndex: 1, explanation: 'ICSI directly injects one sperm into the egg cytoplasm, useful for severe male infertility cases.', difficulty: 'medium' },
  { id: 'rh-41', type: 'mcq', question: 'Artificial Insemination (AI) is a technique in which semen (either from the husband or a donor) is:', options: ['Injected directly into the fallopian tube surgically only', 'Artificially introduced either into the vagina or into the uterus of the female', 'Only used to fertilise eggs outside the body', 'Only performed on animals, not humans'], correctIndex: 1, explanation: 'AI involves artificially introducing collected semen into the vagina or uterus to bypass issues like low sperm count.', difficulty: 'medium' },
  { id: 'rh-42', type: 'mcq', question: 'Surrogate mother arrangements, sometimes used in ART, involve:', options: ['The genetic mother carrying her own pregnancy to term as usual', 'Another woman carrying an embryo (often not genetically hers) to term for the intended parents', 'A completely non-biological, purely legal process with no pregnancy involved', 'Only male partners undergoing the procedure'], correctIndex: 1, explanation: 'A surrogate mother carries the pregnancy (often using the intended parents\' embryo) to term on behalf of another couple.', difficulty: 'medium' },
  { id: 'rh-43', type: 'mcq', question: 'Amniocentesis, a technique originally developed to detect genetic disorders in the developing foetus, has been widely misused for:', options: ['Determining foetal blood type only', 'Determining the sex of the foetus, often leading to female foeticide', 'Measuring maternal blood pressure', 'Testing for maternal diabetes'], correctIndex: 1, explanation: 'Amniocentesis has been notoriously misused for sex determination, contributing to female foeticide.', difficulty: 'medium' },
  { id: 'rh-44', type: 'mcq', question: 'In India, the use of amniocentesis and other techniques for foetal sex determination (for non-medical reasons) has been:', options: ['Actively encouraged by law', 'Legally banned under specific legislation (PCPNDT Act)', 'Left entirely unregulated', 'Only banned for private hospitals, not government ones'], correctIndex: 1, explanation: 'The PCPNDT Act (Pre-Conception and Pre-Natal Diagnostic Techniques Act) legally bans sex determination for non-medical reasons in India.', difficulty: 'medium' },
  { id: 'rh-45', type: 'mcq', question: 'Population stabilisation efforts in India have included widespread promotion of:', options: ['Large family norms', 'The small family norm, alongside incentives for delayed marriage/childbearing', 'Discouraging all forms of contraception', 'Discontinuing sex education entirely'], correctIndex: 1, explanation: 'Promoting the small family norm has been a central strategy for population stabilisation in India.', difficulty: 'medium' },
  { id: 'rh-46', type: 'mcq', question: 'Widespread information about reproduction-related aspects has helped change society\'s general attitude towards which of the following?', options: ['Sex education, family planning, and problems related to adolescence and STDs', 'Only agricultural practices', 'Only industrial pollution', 'Only literacy rates unrelated to health'], correctIndex: 0, explanation: 'Increased awareness has shifted attitudes on sex education, family planning, adolescence, and STDs.', difficulty: 'medium' },
  { id: 'rh-47', type: 'mcq', question: 'Which of the following best explains why barrier contraceptive methods (unlike most hormonal methods) also help control the spread of STDs?', options: ['They alter hormone levels significantly', 'They create a physical barrier that also blocks pathogen transmission during intercourse', 'They are always combined with antibiotics', 'They work only after fertilisation has occurred'], correctIndex: 1, explanation: 'The same physical barrier that blocks sperm also blocks many STD-causing pathogens during intercourse.', difficulty: 'medium' },
  { id: 'rh-48', type: 'mcq', question: 'The Lippes Loop is an example of a:', options: ['Hormone-releasing IUD', 'Non-medicated (inert) IUD', 'Oral contraceptive pill', 'Surgical sterilisation method'], correctIndex: 1, explanation: 'The Lippes Loop is a classic non-medicated (inert) IUD, as opposed to copper- or hormone-releasing types.', difficulty: 'hard' },
  { id: 'rh-49', type: 'mcq', question: 'Which of the following would be an appropriate reason to seek medical advice/counselling before choosing a contraceptive method?', options: ['To ensure the method suits individual health conditions and needs, minimising side effects', 'Because all contraceptives work identically regardless of health status', 'Because contraceptives never need supervision', 'Because only surgical methods require medical involvement'], correctIndex: 0, explanation: 'Individual health factors influence which contraceptive method is most suitable and safe, warranting medical guidance.', difficulty: 'medium' },
  { id: 'rh-50', type: 'mcq', question: 'Which of the following best summarises the overall goal of reproductive health programmes and policies?', options: ['Eliminating reproduction entirely from society', 'Creating a physically, mentally, and socially healthy population with informed reproductive choices', 'Restricting all forms of medical intervention in reproduction', 'Focusing exclusively on population increase without regard to health'], correctIndex: 1, explanation: 'The overarching aim is a reproductively and socially healthy population making informed choices, not simply increasing or decreasing numbers.', difficulty: 'medium' },

  // ---- Assertion-Reason ----
  { id: 'rh-ar-1', type: 'assertion-reason', question: 'Assertion (A): Sex education in schools should be encouraged.\nReason (R): Proper information about reproduction-related aspects helps discourage myths and misconceptions among young people.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'Countering myths/misconceptions with accurate information is exactly why sex education is valuable.', difficulty: 'medium' },
  { id: 'rh-ar-2', type: 'assertion-reason', question: 'Assertion (A): Untreated STDs can lead to infertility.\nReason (R): Some STDs, if left untreated, can damage the reproductive tract and impair fertility.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'This reproductive tract damage mechanism is exactly why untreated STDs can cause infertility.', difficulty: 'medium' },
  { id: 'rh-ar-3', type: 'assertion-reason', question: 'Assertion (A): HIV/AIDS is a curable sexually transmitted disease.\nReason (R): HIV/AIDS is caused by a virus that can be completely eliminated with a short course of antibiotics.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 3, explanation: 'Both are false — HIV/AIDS is NOT curable, and antibiotics (which target bacteria) are ineffective against this viral infection.', difficulty: 'medium' },
  { id: 'rh-ar-4', type: 'assertion-reason', question: 'Assertion (A): Condoms help prevent both pregnancy and STDs.\nReason (R): Condoms act as a barrier that blocks both sperm and many disease-causing pathogens during intercourse.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'This dual physical-blocking action is exactly why condoms protect against both pregnancy and STDs.', difficulty: 'medium' },
  { id: 'rh-ar-5', type: 'assertion-reason', question: 'Assertion (A): Copper ions released by CuT IUDs increase phagocytosis of sperm within the uterus.\nReason (R): This copper-ion effect is one mechanism by which CuT IUDs act as contraceptives.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'Increased sperm phagocytosis via copper ions is directly one of the ways CuT IUDs prevent pregnancy.', difficulty: 'medium' },
  { id: 'rh-ar-6', type: 'assertion-reason', question: 'Assertion (A): Oral contraceptive pills must be taken regularly for a specified period to be effective.\nReason (R): Missing pills can disrupt the hormonal suppression of ovulation, reducing contraceptive effectiveness.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'Disrupted hormone suppression from missed doses is exactly why consistent, regular use is required.', difficulty: 'medium' },
  { id: 'rh-ar-7', type: 'assertion-reason', question: 'Assertion (A): Saheli is a steroidal daily-use contraceptive pill.\nReason (R): Saheli is a non-steroidal preparation taken once a week.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Saheli is actually non-steroidal and taken weekly, not daily/steroidal (A is false); R correctly describes its actual nature.', difficulty: 'medium' },
  { id: 'rh-ar-8', type: 'assertion-reason', question: 'Assertion (A): Vasectomy and tubectomy are reversible contraceptive methods.\nReason (R): These surgical sterilisation procedures block the vas deferens (in males) or fallopian tubes (in females).', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'These methods are generally considered permanent, not reversible (A is false); R correctly describes the surgical mechanism involved.', difficulty: 'medium' },
  { id: 'rh-ar-9', type: 'assertion-reason', question: 'Assertion (A): Medical Termination of Pregnancy (MTP) is safest during the first trimester.\nReason (R): Complication risks associated with abortion increase significantly in later stages of pregnancy.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'Increasing risk with advancing pregnancy is exactly why the first trimester is the safest window for MTP.', difficulty: 'medium' },
  { id: 'rh-ar-10', type: 'assertion-reason', question: 'Assertion (A): Legalising MTP has increased the number of unsafe abortions in India.\nReason (R): Legal, medically supervised abortion access reduces reliance on unsafe, illegal procedures.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Legal MTP access has actually DECREASED unsafe abortions, not increased them (A is false); R correctly explains why legalisation helps reduce unsafe procedures.', difficulty: 'medium' },
  { id: 'rh-ar-11', type: 'assertion-reason', question: 'Assertion (A): Infertility can affect either partner in a couple.\nReason (R): Infertility causes can arise from issues in either the male or female reproductive system, or both.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: "The possibility of causes originating from either partner's reproductive system is exactly why infertility can affect either or both.", difficulty: 'medium' },
  { id: 'rh-ar-12', type: 'assertion-reason', question: "Assertion (A): IVF is popularly known as the 'test tube baby' technique.\nReason (R): In IVF, fertilisation occurs inside the mother's body under laboratory supervision.", options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 2, explanation: "A is true (IVF is indeed popularly called this), but R is false — fertilisation in IVF actually occurs OUTSIDE the body, in a laboratory dish.", difficulty: 'medium' },
  { id: 'rh-ar-13', type: 'assertion-reason', question: 'Assertion (A): ZIFT involves transferring an early embryo into the fallopian tube.\nReason (R): ZIFT stands for Zygote Intra-Fallopian Transfer.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'This is exactly what the acronym ZIFT describes and refers to.', difficulty: 'medium' },
  { id: 'rh-ar-14', type: 'assertion-reason', question: 'Assertion (A): GIFT involves transferring a fully developed embryo into the uterus.\nReason (R): GIFT stands for Gamete Intra-Fallopian Transfer, involving transfer of ova (not an embryo) into the fallopian tube.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'GIFT actually transfers gametes (ova), not a fully developed embryo, and into the fallopian tube, not the uterus (A is false); R correctly describes the real GIFT procedure.', difficulty: 'medium' },
  { id: 'rh-ar-15', type: 'assertion-reason', question: 'Assertion (A): ICSI is particularly useful in cases of severe male infertility.\nReason (R): ICSI involves directly injecting a single sperm into the cytoplasm of the ovum, bypassing many natural barriers to fertilisation.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'Bypassing natural sperm-function barriers is exactly why ICSI helps in severe male infertility cases.', difficulty: 'medium' },
  { id: 'rh-ar-16', type: 'assertion-reason', question: 'Assertion (A): Artificial insemination is used when the male partner has a low sperm count.\nReason (R): Artificial insemination involves collecting and artificially introducing semen into the vagina or uterus.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 1, explanation: 'Both statements are true, but R describes the general procedure of AI rather than specifically explaining why it helps with low sperm count cases.', difficulty: 'hard' },
  { id: 'rh-ar-17', type: 'assertion-reason', question: 'Assertion (A): Amniocentesis was originally developed to detect chromosomal/genetic disorders in the foetus.\nReason (R): It has since been widely misused to determine foetal sex, contributing to female foeticide.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 1, explanation: 'Both statements are true, but R describes a subsequent misuse of the technique rather than explaining its original medical purpose.', difficulty: 'medium' },
  { id: 'rh-ar-18', type: 'assertion-reason', question: 'Assertion (A): Sex determination of a foetus for non-medical reasons is legal in India.\nReason (R): The PCPNDT Act bans sex determination techniques for non-medical purposes.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Non-medical sex determination is actually ILLEGAL in India (A is false), precisely because of the PCPNDT Act (R is true).', difficulty: 'medium' },
  { id: 'rh-ar-19', type: 'assertion-reason', question: 'Assertion (A): Promoting the small family norm has been part of population stabilisation efforts in India.\nReason (R): Smaller family sizes can help reduce the overall rate of population growth over time.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'Reducing growth rate through smaller families is exactly why this norm has been promoted as policy.', difficulty: 'medium' },
  { id: 'rh-ar-20', type: 'assertion-reason', question: 'Assertion (A): A surrogate mother is always the genetic mother of the child she carries.\nReason (R): In surrogacy, another woman carries a pregnancy — often using an embryo formed from the intended parents\' gametes — on behalf of a couple.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'A surrogate is often NOT the genetic mother, since the embryo may come from the intended parents (A is false); R correctly describes this arrangement.', difficulty: 'medium' },

  // ---- Statement-based ----
  { id: 'rh-st-1', type: 'statement', question: 'Statement I: Reproductive health means only the absence of any reproductive disease.\nStatement II: Reproductive health includes physical, emotional, behavioural, and social wellbeing related to reproduction.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — reproductive health is broader than mere disease absence; Statement II correctly captures its holistic scope.', difficulty: 'medium' },
  { id: 'rh-st-2', type: 'statement', question: 'Statement I: Gonorrhoea and syphilis are bacterial STDs.\nStatement II: Genital herpes and HIV/AIDS are viral STDs.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly classify these STDs by their causative agent type.', difficulty: 'medium' },
  { id: 'rh-st-3', type: 'statement', question: 'Statement I: Most STDs, except a few like HIV/AIDS and genital herpes, are fully curable if detected and treated early.\nStatement II: STDs, if left untreated, never lead to any complications.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — untreated STDs can lead to serious complications, including infertility.', difficulty: 'medium' },
  { id: 'rh-st-4', type: 'statement', question: 'Statement I: Barrier methods of contraception include condoms, diaphragms, and cervical caps.\nStatement II: Barrier methods also help reduce the risk of STDs.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe barrier contraceptive methods and their added STD-prevention benefit.', difficulty: 'medium' },
  { id: 'rh-st-5', type: 'statement', question: 'Statement I: Copper-releasing IUDs work partly by increasing phagocytosis of sperm within the uterus.\nStatement II: Hormone-releasing IUDs work by making the uterus unsuitable for implantation.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements accurately describe the respective mechanisms of copper- and hormone-releasing IUDs.', difficulty: 'medium' },
  { id: 'rh-st-6', type: 'statement', question: 'Statement I: Oral contraceptive pills contain either progestogen alone or a progestogen-oestrogen combination.\nStatement II: Oral contraceptive pills have no effect on ovulation.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — oral pills specifically work by inhibiting ovulation.', difficulty: 'medium' },
  { id: 'rh-st-7', type: 'statement', question: 'Statement I: Vasectomy involves cutting and blocking a part of the vas deferens.\nStatement II: Tubectomy involves cutting and blocking a part of the fallopian tube.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the respective male and female sterilisation procedures.', difficulty: 'easy' },
  { id: 'rh-st-8', type: 'statement', question: 'Statement I: MTP is considered safest when performed during the first trimester.\nStatement II: Legalising MTP has helped reduce the incidence of unsafe illegal abortions.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe MTP safety timing and the public health benefit of legalisation.', difficulty: 'medium' },
  { id: 'rh-st-9', type: 'statement', question: 'Statement I: Infertility can result from problems in either the male or female partner.\nStatement II: Assisted Reproductive Technologies (ART) can help many infertile couples have children.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements accurately describe infertility and how ART can address it.', difficulty: 'medium' },
  { id: 'rh-st-10', type: 'statement', question: 'Statement I: In IVF, fertilisation occurs inside the fallopian tube of the mother.\nStatement II: In IVF, fertilisation occurs outside the body, in a laboratory setting.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — IVF fertilisation happens outside the body, as correctly described in Statement II.', difficulty: 'medium' },
  { id: 'rh-st-11', type: 'statement', question: 'Statement I: ZIFT involves transferring an early embryo (up to 8 blastomeres) into the fallopian tube.\nStatement II: GIFT involves transferring donor ova into the fallopian tube of a recipient.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the ZIFT and GIFT procedures respectively.', difficulty: 'medium' },
  { id: 'rh-st-12', type: 'statement', question: 'Statement I: ICSI involves injecting a single sperm directly into the cytoplasm of an ovum.\nStatement II: ICSI is a natural fertilisation process requiring no laboratory intervention.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — ICSI is a highly specialised laboratory-assisted technique, not a natural process.', difficulty: 'medium' },
  { id: 'rh-st-13', type: 'statement', question: 'Statement I: Amniocentesis was originally developed for detecting genetic/chromosomal disorders in the foetus.\nStatement II: Amniocentesis has been misused for sex determination, contributing to female foeticide.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the original purpose of amniocentesis and its subsequent misuse.', difficulty: 'medium' },
  { id: 'rh-st-14', type: 'statement', question: 'Statement I: The PCPNDT Act permits sex determination of a foetus for any reason.\nStatement II: The PCPNDT Act bans sex determination for non-medical purposes.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — the Act specifically bans non-medical sex determination, as correctly described in Statement II.', difficulty: 'medium' },
  { id: 'rh-st-15', type: 'statement', question: 'Statement I: Population stabilisation efforts in India have promoted the small family norm.\nStatement II: Sex education and awareness programmes have played no role in reproductive health improvement.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — sex education and awareness have played a significant role in improving reproductive health outcomes.', difficulty: 'medium' },

  // ---- "How many of the following are correct" ----
  { id: 'rh-hm-1', type: 'statement', question: 'How many of the following are examples of natural (non-device, non-hormonal) contraceptive methods?\nPeriodic abstinence (rhythm method), Coitus interruptus (withdrawal), Lactational amenorrhea, Copper-T (IUD)', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Periodic abstinence, withdrawal, and lactational amenorrhea are natural methods; Copper-T is a device-based (IUD) method, not natural.', difficulty: 'medium' },
  { id: 'rh-hm-2', type: 'statement', question: 'How many of the following are examples of barrier contraceptive methods?\nCondoms, Diaphragms, Cervical caps, Oral contraceptive pills', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Condoms, diaphragms, and cervical caps are barrier methods; oral pills are a hormonal method, not a barrier method.', difficulty: 'easy' },
  { id: 'rh-hm-3', type: 'statement', question: 'How many of the following are surgical methods of contraception (sterilisation)?\nVasectomy, Tubectomy, IUD insertion, Oral pill use', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Vasectomy and tubectomy are surgical sterilisation methods; IUD insertion and oral pill use are non-surgical methods.', difficulty: 'medium' },
  { id: 'rh-hm-4', type: 'statement', question: 'How many of the following are examples of Assisted Reproductive Technologies (ART)?\nIVF, ZIFT, GIFT, ICSI, Coitus interruptus', options: ['Two', 'Three', 'Four', 'Five'], correctIndex: 2, explanation: 'IVF, ZIFT, GIFT, and ICSI are all ART techniques; coitus interruptus is a natural contraceptive method, unrelated to ART.', difficulty: 'medium' },
  { id: 'rh-hm-5', type: 'statement', question: 'How many of the following are sexually transmitted diseases (STDs)?\nGonorrhoea, Syphilis, Genital herpes, HIV/AIDS, Malaria', options: ['Two', 'Three', 'Four', 'Five'], correctIndex: 2, explanation: 'Gonorrhoea, syphilis, genital herpes, and HIV/AIDS are all STDs; malaria is transmitted by mosquitoes, not sexually.', difficulty: 'medium' },
  { id: 'rh-hm-6', type: 'statement', question: 'How many of the following STDs are considered fully curable if detected and treated early?\nGonorrhoea, Syphilis, Chlamydia infections, HIV/AIDS', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Gonorrhoea, syphilis, and chlamydia infections are generally curable bacterial STDs; HIV/AIDS is not curable.', difficulty: 'medium' },
  { id: 'rh-hm-7', type: 'statement', question: 'How many of the following are characteristics of an ideal contraceptive method?\nUser-friendly, Effective, Reversible (for temporary methods), Free of or with minimal side effects', options: ['One', 'Two', 'Three', 'All four'], correctIndex: 3, explanation: 'All four are widely recognised characteristics of an ideal contraceptive method.', difficulty: 'easy' },
  { id: 'rh-hm-8', type: 'statement', question: 'How many of the following are goals typically associated with Reproductive and Child Health Care (RCH) programmes?\nCreating awareness among people about various reproduction-related aspects, Providing facilities and support for building a reproductively healthy society, Eliminating all forms of medical intervention in reproduction, Encouraging sex education', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Awareness, support facilities, and sex education are genuine RCH goals; eliminating medical intervention entirely is not a stated goal.', difficulty: 'medium' },
  { id: 'rh-hm-9', type: 'statement', question: 'How many of the following statements about amniocentesis are correct?\nIt was originally developed to detect genetic disorders, It has been misused for sex determination, Its use for non-medical sex determination is legally banned in India, It can never be used for any legitimate medical purpose', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three statements are correct; amniocentesis DOES have legitimate medical uses (like detecting genetic disorders), making the fourth statement false.', difficulty: 'medium' },
  { id: 'rh-hm-10', type: 'statement', question: 'How many of the following are reasons why legalising MTP has been considered beneficial for public health?\nIt reduces unsafe illegal abortions, It allows medically supervised termination in appropriate cases, It has completely eliminated all pregnancy complications, It provides women more control over reproductive decisions in certain circumstances', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first, second, and fourth statements are genuine benefits; MTP legalisation has not eliminated ALL pregnancy complications, making the third statement an overstatement.', difficulty: 'medium' },
];

export default questions;
